interface Expression {
  interpret(context: Context): boolean;
}

class ComparisonExpression implements Expression {
  constructor(private field: string, private op: string, private value: string) {}
  interpret(context: Context) {
    return compare(context[this.field], this.op, this.value);
  }
}

class AndExpression implements Expression {
  constructor(private left: Expression, private right: Expression) {}
  interpret(context: Context) { return this.left.interpret(context) && this.right.interpret(context); }
}
class OrExpression implements Expression {
  constructor(private left: Expression, private right: Expression) {}
  interpret(context: Context) { return this.left.interpret(context) || this.right.interpret(context); }
}

